import java.util.*;

public class Main {
    String removeKdigits(String num, int k) {
        for (int iter = 0; iter < k; iter++) {                                      // remove ONE digit at a time, k times
            int bestI = num.length() - 1;                                             // default: non-decreasing, remove the LAST digit
            for (int i = 1; i < num.length(); i++) {                                  // find the first digit that is bigger than its NEXT neighbor
                if (num.charAt(i - 1) > num.charAt(i)) {
                    bestI = i - 1;
                    break;
                }
            }
            num = num.substring(0, bestI) + num.substring(bestI + 1);
        }
        int i = 0;
        while (i < num.length() - 1 && num.charAt(i) == '0') i++;
        return num.substring(i);
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.removeKdigits("1432219", 3));
    }
}

