#include <bits/stdc++.h>
using namespace std;

string removeKdigits(string num, int k) {
    for (int iter = 0; iter < k; iter++) {                                            // remove ONE digit at a time, k times
        int bestI = (int)num.size() - 1;                                                 // default: non-decreasing, remove the LAST digit
        for (int i = 1; i < (int)num.size(); i++) {                                      // find the first digit that is bigger than its NEXT neighbor
            if (num[i - 1] > num[i]) {
                bestI = i - 1;
                break;
            }
        }
        num.erase(bestI, 1);
    }
    int i = 0;
    while (i < (int)num.size() - 1 && num[i] == '0') i++;
    return num.substr(i);
}

int main() {
    cout << removeKdigits("1432219", 3) << endl;
    return 0;
}

