import java.util.*;

public class Main {
    String removeKdigits(String num, int k) {
        Deque<Character> stack = new ArrayDeque<>();                                 // a monotonic NON-DECREASING stack of "kept" digits (front = bottom)
        for (char c : num.toCharArray()) {
            while (k > 0 && !stack.isEmpty() && stack.peekLast() > c) {                  // a bigger digit right before a smaller one: always safe to remove
                stack.pollLast();
                k--;
            }
            stack.addLast(c);
        }

        while (k > 0 && !stack.isEmpty()) {                                              // if removals remain (num was fully non-decreasing), trim from the END
            stack.pollLast();
            k--;
        }

        StringBuilder sb = new StringBuilder();
        for (char c : stack) sb.append(c);
        int i = 0;
        while (i < sb.length() - 1 && sb.charAt(i) == '0') i++;                             // strip any leading zeros
        String result = sb.substring(i);
        return result.isEmpty() ? "0" : result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.removeKdigits("1432219", 3));
    }
}

