string removeKdigits(string num, int k) {
    string stack;                                                                        // using the string itself as a monotonic non-decreasing stack
    for (char c : num) {
        while (k > 0 && !stack.empty() && stack.back() > c) {                                // a bigger digit right before a smaller one: always safe to remove
            stack.pop_back();
            k--;
        }
        stack.push_back(c);
    }

    while (k > 0 && !stack.empty()) {                                                        // if removals remain (num was fully non-decreasing), trim from the END
        stack.pop_back();
        k--;
    }

    int i = 0;
    while (i < (int)stack.size() - 1 && stack[i] == '0') i++;                                   // strip any leading zeros
    string result = stack.substr(i);
    return result.empty() ? "0" : result;
}

